INSERT INTO `broadcast_text` (`Text`,`Text1`,`ID`,`LanguageID`,`ConditionID`,`EmotesID`,`Flags`,`ChatBubbleDurationMs`,`VoiceOverPriorityID`,`SoundKitID1`,`SoundKitID2`,`EmoteID1`,`EmoteID2`,`EmoteID3`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`VerifiedBuild`) VALUES
('К сожалению, слухи о нашем бедственном положении правдивы. Сбои в работе силовых линий повлекли за собой волнение чародейских сил, которыми пронизан наш город.\r\n\r\nТеперь, когда Даларан намеревается вот-вот снова открыть свои границы нашим союзникам, нужно как можно скорее найти решение нашей проблемы.','',299703,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70450);
INSERT INTO `broadcast_text_locale` (`ID`,`locale`,`Text_lang`,`Text1_lang`,`VerifiedBuild`) VALUES
(299703,'ruRU','К сожалению, слухи о нашем бедственном положении правдивы. Сбои в работе силовых линий повлекли за собой волнение чародейских сил, которыми пронизан наш город.\r\n\r\nТеперь, когда Даларан намеревается вот-вот снова открыть свои границы нашим союзникам, нужно как можно скорее найти решение нашей проблемы.','',70450);
